const languageIndex = { tn: 0, zu: 1, xh: 2, af: 3, st: 4, ve: 5, nso: 6, nr: 7, ss: 8, ts: 9 }

export function translate(lang, text, values = {}) {
  const index = languageIndex[lang]
  let result = index === undefined ? text : (copy[text]?.[index] || additionalCopy[lang]?.[text] || text)
  for (const [key, value] of Object.entries(values)) {
    result = result.replaceAll(`{${key}}`, String(value))
  }
  return result
}

export function translateMaterial(material, lang) {
  if (!material || lang === 'en' || languageIndex[lang] === undefined) return material
  const withTopic = (prefix, topic) => `${prefix}${prefix.endsWith('-') ? '' : ' '}${topic}`
  const dynamicTranslations = [
    [/^Let's learn about (.+)$/, (topic) => withTopic(translate(lang, 'Let’s learn about'), topic)],
    [/^Today we learn about (.+)\.$/, (topic) => `${withTopic(translate(lang, 'Today we learn about'), topic)}.`],
    [/^Think of where you see (.+) at home or on the way to school\.$/, (topic) => translate(lang, 'Think of where you see {topic} at home or on the way to school.', { topic })],
    [/^With a buddy, find two things in the classroom that show (.+)\. Draw them in your book\.$/, (topic) => translate(lang, 'With a buddy, find two things in the classroom that show {topic}. Draw them in your book.', { topic })],
  ]
  const translateValue = (value) => {
    if (typeof value === 'string') {
      for (const [pattern, render] of dynamicTranslations) {
        const match = value.match(pattern)
        if (match) return render(match[1])
      }
      return translate(lang, value)
    }
    if (Array.isArray(value)) return value.map(translateValue)
    if (value && typeof value === 'object') {
      return Object.fromEntries(Object.entries(value).map(([key, item]) => [
        key,
        key === 'fraction' ? item : translateValue(item),
      ]))
    }
    return value
  }
  return translateValue(material)
}
